window.WORD_AI_EXAMPLE_CHUNK = {"entries":{"carpenter":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"木匠"}],"examples":[{"sentence":"The experienced carpenter restored the damaged staircase without altering its original character.","translation":"这位经验丰富的木匠修复了受损的楼梯，同时保留了它原有的特色。","targetForm":"carpenter","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Before cutting the oak boards, the carpenter measured each corner of the room twice.","translation":"在切割橡木板之前，木匠把房间的每个角落都测量了两遍。","targetForm":"carpenter","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A local carpenter transformed the neglected attic into a bright and practical study.","translation":"当地的一位木匠把闲置的阁楼改造成了明亮实用的书房。","targetForm":"carpenter","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because the cabinet required unusual joints, the carpenter first built a small wooden model.","translation":"由于这个柜子需要特殊的榫接结构，木匠先制作了一个小型木制模型。","targetForm":"carpenter","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Working beside the open window, the carpenter patiently shaped the curved chair legs by hand.","translation":"木匠在敞开的窗边干活，耐心地用手工制作弯曲的椅腿。","targetForm":"carpenter","senseId":"source-n-1","sourceSenseId":"n-1"}]},"calorie":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"卡路里（热量单位）"}],"examples":[{"sentence":"A balanced diet requires careful monitoring of calorie intake to maintain optimal health.","translation":"均衡的饮食需要仔细监控卡路里摄入量以保持最佳健康状态。","targetForm":"calorie","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The nutritionist explained that one gram of fat contains nine calories, which is more than double the amount in carbohydrates.","translation":"营养师解释说，一克脂肪含有九卡路里，是碳水化合物含量的两倍多。","targetForm":"calories","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Many processed foods are high in empty calories, contributing to weight gain without providing essential nutrients.","translation":"许多加工食品含有高热量但缺乏营养，导致体重增加却不提供必需营养素。","targetForm":"calories","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Athletes often require a higher calorie consumption to fuel their intense training regimens and aid recovery.","translation":"运动员通常需要更高的卡路里消耗，以为其高强度训练提供能量并促进恢复。","targetForm":"calorie","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The concept of a calorie originated from early experiments measuring the heat produced by burning food.","translation":"卡路里的概念源于早期测量食物燃烧产生热量的实验。","targetForm":"calorie","senseId":"source-n-1","sourceSenseId":"n-1"}]},"cafe":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"咖啡馆；咖啡店"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"酒店","contextReviewed":true}],"examples":[{"sentence":"The cafe on the corner, which roasts its own beans, serves excellent espresso and homemade pastries throughout the day.","translation":"街角那家自己烘焙咖啡豆的咖啡馆全天供应优质的浓缩咖啡和自制糕点。","targetForm":"cafe","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"After the renovation, the cafe expanded its menu to include light lunches and specialty teas, thereby attracting a broader clientele.","translation":"翻新后，这家咖啡馆扩展了菜单，增加了简餐和特色茶饮，从而吸引了更广泛的顾客。","targetForm":"cafe","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"She spent the afternoon reading in a quiet cafe that overlooked the bustling city square, where she could observe the ebb and flow of urban life.","translation":"她整个下午都在一家安静的咖啡馆里读书，那里可以俯瞰熙熙攘攘的城市广场，观察城市生活的潮起潮落。","targetForm":"cafe","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The hotel's cafe offers a continental breakfast buffet with fresh fruits and pastries, although guests may also order à la carte items.","translation":"酒店的咖啡馆提供欧陆式自助早餐，包括新鲜水果和糕点，不过客人也可以单点菜品。","targetForm":"cafe","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Guests can enjoy a relaxed dinner at the cafe, which features local cuisine and a selection of wines, provided they make a reservation in advance.","translation":"客人可以在咖啡馆享用轻松的晚餐，那里提供当地美食和精选葡萄酒，前提是他们提前预订。","targetForm":"cafe","senseId":"source-n-2","sourceSenseId":"n-2"}]},"camp":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"露营"}],"examples":[{"sentence":"In the end, both camps should show greater humility: macro-development practitioners about what they already know, and micro-development practitioners about what they can learn.","translation":"最后，两大阵营应该更加谦逊：宏观发展实践者不能思而不学，微观发展实践者不能学而不思。","targetForm":"camps","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Most of the traffic coming into this seaside town is heading for the beachside holiday camp.","translation":"进入这座海滨小镇的车辆大多是前往海边度假营地的。","targetForm":"camp","senseId":"source-n-1","sourceSenseId":"n-1"}]},"campaign":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"战役"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"运动"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"竞选运动"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"参加运动"}],"examples":[{"sentence":"The history course examined a military campaign by comparing maps, letters, and accounts written by people on both sides.","translation":"历史课通过比较双方人员写下的地图、信件和记述来研究一场军事战役。","targetForm":"campaign","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the campaign began locally, it gained national attention after schools and libraries joined the effort.","translation":"尽管这场运动起初是地方性的，在学校和图书馆加入后，它获得了全国关注。","targetForm":"campaign","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The mayoral campaign focused on housing, transport, and how public money should be spent in the following year.","translation":"市长竞选活动聚焦住房、交通以及下一年度公共资金应如何使用。","targetForm":"campaign","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Before the vote, volunteers campaigned in several neighbourhoods and recorded questions raised by local residents.","translation":"投票前，志愿者在多个社区开展竞选活动，并记录当地居民提出的问题。","targetForm":"campaigned","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The charity campaigned for safer crossings after collecting evidence from families affected by traffic accidents.","translation":"慈善机构收集受交通事故影响家庭的证据后，为更安全的过街设施开展倡导活动。","targetForm":"campaigned","senseId":"source-v-1","sourceSenseId":"v-1"}]},"camel":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"骆驼"}],"examples":[{"sentence":"Although the camel is often associated with arid deserts, it also thrives in the cold steppes of Central Asia.","translation":"尽管骆驼常与干旱沙漠联系在一起，但它在中亚寒冷的草原上也能茁壮成长。","targetForm":"camel","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because a camel can survive for weeks without water, it remains an essential companion for travelers crossing the Sahara.","translation":"因为骆驼可以在没有水的情况下存活数周，它仍然是穿越撒哈拉的旅行者必不可少的伙伴。","targetForm":"camel","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"While a camel can carry heavy loads over long distances, its pace is much slower than that of a horse.","translation":"虽然骆驼可以长距离搬运重物，但它的速度比马慢得多。","targetForm":"camel","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"In many traditional societies, the camel is valued not only for transportation but also for its milk, which is highly nutritious.","translation":"在许多传统社会中，骆驼不仅因其运输能力而受到重视，还因其营养丰富的奶而受到珍视。","targetForm":"camel","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The camel can go a long time without water and food.","translation":"骆驼可以撑很久不吃不喝。","targetForm":"camel","senseId":"source-n-1","sourceSenseId":"n-1"}]},"cab":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"出租车"}],"examples":[{"sentence":"Because the conference venue was far from the hotel, the organizers arranged a cab for each participant.","translation":"由于会议地点离酒店很远，组织者为每位与会者安排了一辆出租车。","targetForm":"cab","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The researcher used a cab to transport the fragile equipment, thereby avoiding potential damage on the bus.","translation":"那位研究员用出租车运送易碎设备，从而避免了在公交车上可能造成的损坏。","targetForm":"cab","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the subway is cheaper, I often take a cab when I am running late for an important meeting.","translation":"尽管地铁更便宜，但当我要赶一个重要会议时，我经常乘坐出租车。","targetForm":"cab","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"If you are unfamiliar with the city, hailing a cab can be a safer option than navigating public transport alone.","translation":"如果你对这座城市不熟悉，叫一辆出租车可能比独自乘坐公共交通更安全。","targetForm":"cab","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"While waiting for a cab in the rain, she realized that she had left her presentation notes at the office.","translation":"在雨中等待出租车时，她意识到她把演示笔记忘在了办公室。","targetForm":"cab","senseId":"source-n-1","sourceSenseId":"n-1"}]},"campus":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"校园"}],"examples":[{"sentence":"When traveling to Hsinchu, you must not miss the beautiful campuses of National Tsing Hua University and National Chiao Tung University.","translation":"去新竹旅游，不可错过清大、交大校园的美景。","targetForm":"campuses","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"In the center of the university campus stands the statue of the founder.","translation":"创校人的雕像在大学校园的中心矗立着。","targetForm":"campus","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"I took him to the most expensive restaurant on campus.","translation":"我把他带到校区里最贵的餐馆去了。","targetForm":"campus","senseId":"source-n-1","sourceSenseId":"n-1"}]},"calculate":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"计算"}],"examples":[{"sentence":"Although the data set is incomplete, we can still calculate a preliminary estimate of the project's total cost.","translation":"尽管数据集不完整，我们仍然可以计算出项目总成本的初步估计。","targetForm":"calculate","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Engineers must calculate the load-bearing capacity of the bridge before construction begins, thereby ensuring public safety.","translation":"工程师必须在施工开始前计算出桥梁的承载能力，从而确保公共安全。","targetForm":"calculate","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"If we calculate the carbon footprint of each product, consumers can make more informed choices that benefit the environment.","translation":"如果我们计算每种产品的碳足迹，消费者就能做出更明智的选择，从而有利于环境。","targetForm":"calculate","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"To calculate the company's annual revenue accurately, the accountant compiled data from all regional offices, rather than relying on estimates.","translation":"为了准确计算公司的年收入，会计汇总了所有地区办事处的数据，而不是依赖估算。","targetForm":"calculate","senseId":"source-v-1","sourceSenseId":"v-1"}]},"cabbage":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"卷心菜"}],"examples":[{"sentence":"Because cabbage is rich in vitamins and affordable, it has become a staple in many school lunch programs.","translation":"由于卷心菜富含维生素且价格实惠，它已成为许多学校午餐计划中的主食。","targetForm":"cabbage","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Nutritionists recommend including cabbage in one's diet because its high fiber content aids digestion and promotes gut health.","translation":"营养学家建议在饮食中加入卷心菜，因为其高纤维含量有助于消化并促进肠道健康。","targetForm":"cabbage","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although cabbage is often underestimated, it can be transformed into a delicious dish when braised with a few simple seasonings.","translation":"尽管卷心菜常常被低估，但用几种简单的调料炖煮后，它就能变成一道美味的菜肴。","targetForm":"cabbage","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Farmers in the region have started to cultivate cabbage as a winter crop, which has significantly increased their annual income.","translation":"该地区的农民开始种植卷心菜作为冬季作物，这大大增加了他们的年收入。","targetForm":"cabbage","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"In many cultures, fermented cabbage is a traditional food that not only preserves the vegetable but also enhances its nutritional value.","translation":"在许多文化中，发酵卷心菜是一种传统食品，它不仅保存了蔬菜，还提高了其营养价值。","targetForm":"cabbage","senseId":"source-n-1","sourceSenseId":"n-1"}]},"cattle":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"牛"}],"examples":[{"sentence":"Because cattle produce significant amounts of methane, researchers are exploring dietary supplements that can reduce these emissions.","translation":"由于牛产生大量甲烷，研究人员正在探索能够减少这些排放的饲料添加剂。","targetForm":"cattle","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The ancient cave paintings depict cattle with remarkable detail, which suggests that these animals held great cultural significance.","translation":"古代洞穴壁画以惊人的细节描绘了牛，这表明这些动物具有重要的文化意义。","targetForm":"cattle","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although cattle are often associated with pastoral landscapes, their breeding has become a highly industrialized process in many countries.","translation":"尽管牛通常与田园风光联系在一起，但在许多国家，牛的养殖已成为高度工业化的过程。","targetForm":"cattle","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"When a severe drought struck the region, many farmers were forced to sell their cattle at a loss to survive.","translation":"当严重干旱袭击该地区时，许多农民被迫亏本出售牛以求生存。","targetForm":"cattle","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The nomadic tribes relied on their cattle not only for milk and meat but also as a form of currency in trade.","translation":"游牧部落不仅依赖牛获取牛奶和肉，还将其作为贸易中的一种货币形式。","targetForm":"cattle","senseId":"source-n-1","sourceSenseId":"n-1"}]},"candle":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"蜡烛"}],"examples":[{"sentence":"Although the candle burned brightly, it could not dispel the deep shadows in the old library.","translation":"尽管蜡烛明亮燃烧，它仍无法驱散旧图书馆里浓重的阴影。","targetForm":"candle","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because the candle was made from beeswax, it gave off a light honey fragrance in the room.","translation":"由于蜡烛由蜂蜡制成，它在房间里散发出淡淡的蜂蜜香味。","targetForm":"candle","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"She placed a candle on the windowsill, which created a warm light visible from the garden.","translation":"她把一支蜡烛放在窗台上，营造出从花园也能看到的温暖光亮。","targetForm":"candle","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"While the power was out, the family gathered around a single candle and shared stories.","translation":"停电时，一家人围着一支蜡烛聚在一起分享故事。","targetForm":"candle","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The candle flickered in the draft, yet it continued to burn through the night.","translation":"蜡烛在穿堂风中摇曳，却一直燃烧到夜里。","targetForm":"candle","senseId":"source-n-1","sourceSenseId":"n-1"}]},"catch":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"捕捉"}],"examples":[{"sentence":"It is time for the rest of Central and Eastern Europe to catch up to Serbia.","translation":"现在是其他中东欧国家向塞尔维亚看齐的时候了。","targetForm":"catch","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the accident has delayed progress by one month, we have managed to catch up with the schedule.","translation":"尽管事故使进度延迟了一个月，我们还是设法赶上了日程表。","targetForm":"catch","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Laws are like cobwebs, which may catch small flies, but let wasps and hornets break through.","translation":"法网就像蜘蛛网，网得住苍蝇蚊子，网不住豺狼老虎。","targetForm":"catch","senseId":"source-n-1","sourceSenseId":"n-1"}]},"cap":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"盖子"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"帽子"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"覆盖"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"胜过"}],"examples":[{"sentence":"The government imposed a cap on carbon emissions, which forced industries to adopt cleaner technologies.","translation":"政府对碳排放设定了上限，这迫使工业采用更清洁的技术。","targetForm":"cap","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The graduate wore a traditional academic cap during the ceremony, symbolizing the culmination of years of study.","translation":"这位毕业生在典礼上戴着传统的学位帽，象征着多年学习的圆满结束。","targetForm":"cap","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"A layer of snow capped the mountain peaks, creating a breathtaking contrast against the clear blue sky.","translation":"一层积雪覆盖了山顶，与清澈的蓝天形成了令人叹为观止的对比。","targetForm":"capped","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The new policy caps annual rent increases at three percent, providing stability for tenants in a volatile market.","translation":"新政策将年租金涨幅限制在百分之三，为动荡市场中的租户提供了稳定性。","targetForm":"caps","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The director's latest film caps a remarkable career, earning critical acclaim and numerous international awards.","translation":"这位导演的最新电影为其卓越的职业生涯画上了圆满的句号，赢得了评论界的赞誉和众多国际奖项。","targetForm":"caps","senseId":"source-v-3","sourceSenseId":"v-3"}]},"canteen":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"水壶"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"军中俱乐部"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"临时流动餐馆"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"小卖部"}],"examples":[{"sentence":"Before the hike, each student filled a canteen because drinking water would not be available on the trail.","translation":"徒步前，每名学生都装满水壶，因为山路上没有饮用水供应。","targetForm":"canteen","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The soldiers met in the canteen after training, where they could rest and write letters home.","translation":"训练后，士兵们在军营食堂会面，在那里休息并给家里写信。","targetForm":"canteen","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"When the festival began, a mobile canteen served simple meals near the entrance.","translation":"节日开始时，一家流动餐馆在入口附近供应简单餐食。","targetForm":"canteen","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Although the school canteen is crowded at lunch, it remains convenient for students with afternoon classes.","translation":"尽管学校食堂午餐时很拥挤，它仍方便下午有课的学生。","targetForm":"canteen","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"Because the hospital canteen stays open overnight, night-shift staff can obtain hot meals.","translation":"由于医院食堂通宵开放，夜班员工能吃到热饭。","targetForm":"canteen","senseId":"source-n-4","sourceSenseId":"n-4"}]},"carrier":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"邮递员"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"运送者"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"带菌者"},{"id":"source-other-1","partOfSpeech":"计算机","sourceSenseIds":["other-1"],"sense":"载波","contextReviewed":true}],"examples":[{"sentence":"The postal carrier delivered the registered letter to the office, which required a signature upon receipt.","translation":"邮递员将挂号信送到了办公室，收件时需要签名。","targetForm":"carrier","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"As a common carrier, the airline is obligated to transport passengers safely to their destinations.","translation":"作为公共承运人，航空公司有义务将乘客安全送达目的地。","targetForm":"carrier","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The letter carrier navigated the icy sidewalks with caution, ensuring every parcel reached its intended address.","translation":"邮递员小心翼翼地走过结冰的人行道，确保每个包裹都送达指定地址。","targetForm":"carrier","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Mosquitoes are notorious carriers of malaria, transmitting the parasite through their bites.","translation":"蚊子是疟疾的臭名昭著的带菌者，通过叮咬传播寄生虫。","targetForm":"carriers","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The telecommunications company uses a high-frequency carrier to transmit data over long distances.","translation":"电信公司使用高频载波远距离传输数据。","targetForm":"carrier","senseId":"source-other-1","sourceSenseId":"other-1"}]},"cargo":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"货物"}],"examples":[{"sentence":"Khaki shorts with cargo pockets do not make you an adventurer.","translation":"单有卡其裤，还成不了冒险家。","targetForm":"cargo","senseId":"source-n-1","sourceSenseId":"n-1"}]},"can":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"装罐"}],"examples":[{"sentence":"Against that backdrop, one can assess current growth patterns in the global economy and its various parts.","translation":"在上述背景下，我们可以对全球经济目前的增长模式及其组成部分进行评估。","targetForm":"can","senseId":"source-v-1","sourceSenseId":"v-1"}]},"cake":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"蛋糕"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"块"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"结块"}],"examples":[{"sentence":"Although the cake looked simple, its lemon filling gave the celebration a memorable finishing touch.","translation":"尽管蛋糕看起来朴素，柠檬馅料仍为庆祝活动增添了令人难忘的收尾。","targetForm":"cake","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"When the cake had cooled completely, the baker added fruit so that the icing would remain smooth.","translation":"蛋糕完全冷却后，烘焙师才加上水果，以便糖霜保持平整。","targetForm":"cake","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The traveller carried a small cake of soap because plastic bottles were impractical for the journey.","translation":"这位旅行者带着一小块肥皂，因为塑料瓶不适合这段行程。","targetForm":"cake","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"If the powder absorbs moisture, it may cake inside the container and become difficult to measure.","translation":"如果粉末吸收了水分，它可能会在容器内结块，变得难以量取。","targetForm":"cake","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Because dust had caked on the tools, the conservator cleaned them before beginning the restoration.","translation":"由于灰尘已经结在工具上，修复师在开始修复前先把它们清理干净。","targetForm":"caked","senseId":"source-v-3","sourceSenseId":"v-3"}]},"cage":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"笼"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"牢房"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"关进笼内"}],"examples":[{"sentence":"The rescue centre replaced the narrow cage with an enclosure that allowed the injured bird to exercise.","translation":"救助中心用一个能让受伤鸟儿活动的围栏，替换了狭窄的笼子。","targetForm":"cage","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the cage was made of strong wire, volunteers checked its lock each morning for safety.","translation":"尽管笼子由坚固的铁丝制成，志愿者仍每天早晨检查锁扣以确保安全。","targetForm":"cage","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"In the historical account, the word cage referred to a cramped prison cell rather than an animal enclosure.","translation":"在这份历史记载中，cage 指的是狭小的牢房，而不是动物围栏。","targetForm":"cage","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"When staff caged the animal for transport, they kept the journey short and monitored it closely.","translation":"工作人员为运输而将动物放入笼中时，尽量缩短行程并密切观察它的状况。","targetForm":"caged","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Fear can cage creative thinking unless a team makes room for respectful disagreement.","translation":"如果团队不给尊重不同意见留出空间，恐惧就会束缚创造性思维。","targetForm":"cage","senseId":"source-v-1","sourceSenseId":"v-1"}]},"canal":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"运河"}],"examples":[{"sentence":"This ship is too big to pass through the canal.","translation":"这艘船太大，没法通过运河。","targetForm":"canal","senseId":"source-n-1","sourceSenseId":"n-1"}]},"calcium":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"化学元素钙","contextReviewed":true}],"examples":[{"sentence":"The science class examined calcium as an element before comparing its properties with those of other metals.","translation":"科学课先研究钙这种元素，再把它的性质与其他金属进行比较。","targetForm":"calcium","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Although calcium appears in many foods, the lesson focused on how the element is used in biology and industry.","translation":"尽管许多食物中含有钙，这节课重点讨论了该元素在生物学和工业中的用途。","targetForm":"calcium","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"When researchers measured calcium in the water, they recorded both the sample location and the time.","translation":"研究人员测量水中的钙时，记录了样品地点和时间。","targetForm":"calcium","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Because calcium compounds occur in common rocks, geologists can use them to study local formations.","translation":"由于钙化合物存在于常见岩石中，地质学家可以用它们研究当地地层。","targetForm":"calcium","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The museum displayed a calcium sample beside a chart explaining where the element appears in the environment.","translation":"博物馆在图表旁展示了钙样品，说明这种元素在环境中的出现位置。","targetForm":"calcium","senseId":"source-n-2","sourceSenseId":"n-2"}]},"catastrophe":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"大灾难"}],"examples":[{"sentence":"Due to the catastrophe caused by the huge tsunami, damage was sustained by the nuclear reactor as well as explosions at the nuclear power plant.","translation":"由于特大海啸的灾害，核能融炉遭受损害，造成了原子能发电站爆炸。","targetForm":"catastrophe","senseId":"source-n-1","sourceSenseId":"n-1"}]},"cause":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"原因"}],"examples":[{"sentence":"These trends can be reversed, but only if we agree on the causes of democratic backsliding and target our solutions accordingly.","translation":"这些趋势是可以扭转的，但条件是我们必须在民主滑坡的原因上取得一致，并据此校准解决方案。","targetForm":"causes","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A third key health trend in 2017 was further progress toward the elimination of human onchocerciasis, which causes blindness, impaired vision, and skin infections.","translation":"2017年的第三项关键性卫生趋势是消灭人类盘尾丝虫病的进程也实现了新的进展，人类盘尾丝虫病会造成失明、视力下降和皮肤感染。","targetForm":"causes","senseId":"source-n-1","sourceSenseId":"n-1"}]},"capsule":{"senseGroups":[{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"胶囊剂","contextReviewed":true},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"胶囊"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"蒴果"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"瓶帽"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"航天舱"}],"examples":[{"sentence":"The pharmacist explained that each capsule should be swallowed whole with water after the evening meal.","translation":"药剂师解释说，每粒胶囊都应在晚餐后用水整粒吞服。","targetForm":"capsule","senseId":"source-n-5","sourceSenseId":"n-5"},{"sentence":"Researchers sealed the powder inside tiny capsules so that it would remain stable during transport.","translation":"研究人员把粉末密封在微小胶囊中，以便它在运输过程中保持稳定。","targetForm":"capsules","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"When the capsule split open, the botanist collected its seeds before the wind scattered them across the slope.","translation":"蒴果裂开后，植物学家在风把种子吹散到山坡各处之前收集了它们。","targetForm":"capsule","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The archivist found a metal capsule beneath the foundation, containing notes left by the original builders.","translation":"档案员在地基下发现了一个金属小容器，里面装着最初建造者留下的笔记。","targetForm":"capsule","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Although the capsule appeared small from the ground, it carried instruments designed to study the upper atmosphere.","translation":"尽管从地面看航天舱很小，它仍搭载了用于研究高层大气的仪器。","targetForm":"capsule","senseId":"source-n-4","sourceSenseId":"n-4"}]},"cancel":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"取消"}],"examples":[{"sentence":"I had to cancel that order because we didn't have enough money to pay for it.","translation":"我们的钱不够，所以我只好把订单取消了。","targetForm":"cancel","senseId":"source-n-1","sourceSenseId":"n-1"}]},"cable":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"电缆"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"海底电报"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"缆"}],"examples":[{"sentence":"Although the cable was buried deep underground, a construction accident severed it and disrupted the entire network.","translation":"尽管电缆深埋地下，但一次施工事故将其切断，导致整个网络中断。","targetForm":"cable","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because the undersea cable transmits data at high speeds, it has become a critical component of global communications.","translation":"由于海底电缆能高速传输数据，它已成为全球通信的关键组成部分。","targetForm":"cable","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Engineers used a durable synthetic cable to replace the worn steel one, thereby extending the elevator's service life.","translation":"工程师用耐用的合成缆绳替换了磨损的钢缆，从而延长了电梯的使用寿命。","targetForm":"cable","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The bridge's main cable, which consists of thousands of steel wires, must be inspected regularly to ensure structural integrity.","translation":"大桥的主缆由数千根钢丝组成，必须定期检查以确保结构完整性。","targetForm":"cable","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"When the power cable failed during the storm, emergency generators activated to maintain essential services.","translation":"当电力电缆在暴风雨中发生故障时，应急发电机启动以维持基本服务。","targetForm":"cable","senseId":"source-n-1","sourceSenseId":"n-1"}]},"carrot":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"胡萝卜"}],"examples":[{"sentence":"In this soup there are carrots, onions, parsley, celery and potatoes.","translation":"这个汤里有胡萝卜、洋葱、欧芹、芹菜和土豆。","targetForm":"carrots","senseId":"source-n-1","sourceSenseId":"n-1"}]},"carbon":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"碳"}],"examples":[{"sentence":"There are few arguments for China and India to commit to carbon caps – and compelling reasons for them to resist pressure to do so.","translation":"有中国和���度应遵守碳排放标准的几个理由 — — 也有它们抵制这样做的压力的令人信服力的理由。","targetForm":"carbon","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Mangroves absorb more carbon dioxide than any other trees on Earth because they have large underground root structures.","translation":"红树林吸取二氧化碳比地球上其他树木都要多，因为它们具有很大的地下根部结构。","targetForm":"carbon","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Carbon dioxide is a gas that is produced every time a fuel such as coal, oil, or natural gas is burned.","translation":"二氧化碳是燃烧煤、石油或天然气这样的燃料时会产生的气体。","targetForm":"carbon","senseId":"source-n-1","sourceSenseId":"n-1"}]},"camera":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"照相机"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"摄影机"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"密谈室"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"暗箱"}],"examples":[{"sentence":"The camera recorded the changing light every hour, allowing the class to compare the shadows across the courtyard.","translation":"相机每小时记录光线变化，让全班能够比较庭院中阴影的变化。","targetForm":"camera","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the camera was compact, its manual controls gave the photographer precise control over focus and exposure.","translation":"尽管这台相机很小巧，它的手动控制仍让摄影师能精确控制对焦和曝光。","targetForm":"camera","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The director placed a second camera near the stage so that the final film could show the performers' expressions.","translation":"导演在舞台旁放置了第二台摄影机，以便最终影片能呈现表演者的表情。","targetForm":"camera","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The committee met in camera while reviewing confidential applications, then published a summary of its decision.","translation":"委员会在不公开的会议中审查保密申请，随后公布了决定摘要。","targetForm":"camera","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The lesson used a camera obscura to demonstrate how light can project an inverted image onto a surface.","translation":"课程使用暗箱演示光线如何把倒置图像投射到一个平面上。","targetForm":"camera","senseId":"source-n-4","sourceSenseId":"n-4"}]},"category":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"种类"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"类项"},{"id":"source-other-1","partOfSpeech":"计算机","sourceSenseIds":["other-1"],"sense":"分类","contextReviewed":true}],"examples":[{"sentence":"The report separates expenditure into each category so that readers can see where public money is being used.","translation":"报告把支出分为各个类别，以便读者看清公共资金被用于何处。","targetForm":"category","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the novel belongs to the historical category, it uses a modern narrator and experimental structure.","translation":"尽管这部小说属于历史类，它仍采用现代叙述者和实验性结构。","targetForm":"category","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Before the exhibition opened, the curator assigned every object to a category that matched its material and period.","translation":"展览开幕前，策展人把每件物品归入与其材质和年代相符的类别。","targetForm":"category","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The database uses a category field to group documents, which allows users to filter long search results quickly.","translation":"该数据库使用分类字段给文件分组，使用户能快速筛选冗长的搜索结果。","targetForm":"category","senseId":"source-other-1","sourceSenseId":"other-1"},{"sentence":"Because each category has its own access rules, the administrator checked the settings before publishing the records.","translation":"由于每个分类都有自己的访问规则，管理员在发布记录前检查了设置。","targetForm":"category","senseId":"source-other-1","sourceSenseId":"other-1"}]},"cassette":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"盒式磁带"}],"examples":[{"sentence":"I got a video cassette recorder cheap at that shop.","translation":"我在那商店花低价买了台录像机。","targetForm":"cassette","senseId":"source-n-1","sourceSenseId":"n-1"}]},"cancer":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"癌"}],"examples":[{"sentence":"Cancer can be cured easily if it is found in its first phase.","translation":"癌症如果在第一阶段被发现的话是很容易治愈的。","targetForm":"cancer","senseId":"source-n-1","sourceSenseId":"n-1"}]},"card":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"卡片"}],"examples":[{"sentence":"Bale needs to be more careful when playing because he’s already been given one yellow card.","translation":"贝尔在踢球时需要更加小心，因为他已经得了一次黄牌了。","targetForm":"card","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"In the nineties, every computer started coming with a sound card, which really kicked off PC gaming.","translation":"在九十年代，每台电脑都开始配备音效卡，真正开启了 PC 游戏的时代。","targetForm":"card","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"When Mike tried to tackle the other player, he pushed him and he was given a yellow card and a warning.","translation":"当迈克试图铲球的时候，他用手推了对方球员一把，结果得到了黄牌警告。","targetForm":"card","senseId":"source-n-1","sourceSenseId":"n-1"}]},"carpet":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"地毯"}],"examples":[{"sentence":"A green carpet will not go with this blue curtain.","translation":"绿色的毯子和这条蓝色的帘子不配。","targetForm":"carpet","senseId":"source-n-1","sourceSenseId":"n-1"}]},"career":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"事业"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"[法] 职业","contextReviewed":true}],"examples":[{"sentence":"More and more women have their own careers and are economically independent of their husbands.","translation":"越来越多的女人拥有自己的事业并实现和丈夫的经济独立。","targetForm":"careers","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"He always kept an open mind about his future career.","translation":"他一直都对他的未来事业保持着开明的心态。","targetForm":"career","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"She seems to devote all her effects to her career.","translation":"她似乎把自己所有的精力都投入到了事业上。","targetForm":"career","senseId":"source-n-1","sourceSenseId":"n-1"}]},"castle":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"城堡"}],"examples":[{"sentence":"When you go to Romania, you will visit Dracula's Castle.","translation":"当你去罗马尼亚的时候，你将会造访吸血鬼之王的城堡。","targetForm":"castle","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"In the most secret chamber of the castle lay the greatest treasure on earth—the Book of Truth.","translation":"在城堡最秘密的密室里有全球宝中之宝——《真理经》。","targetForm":"castle","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"There is an old castle at the foot of the mountain.","translation":"山脚下有一座古老的城堡。","targetForm":"castle","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The river outside of the castle is called a moat.","translation":"城堡外面的河叫做护城河。","targetForm":"castle","senseId":"source-n-1","sourceSenseId":"n-1"}]},"candidate":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"候选人"}],"examples":[{"sentence":"When he did lose, he demanded a recount, not as a candidate, but in his capacity as Commander-in-Chief.","translation":"在伊拉克问题上，唯一能够解释美国政府如此施压来支持伊朗青睐的马利基的原因，就是奥巴马在竞选总统选举时曾经许下要在第一届任期内从伊拉克撤军的诺言。","targetForm":"candidate","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"One hopes that what emerges from the parties’ nominating processes is insight into how the successful candidates answer three big questions.","translation":"人们希望从两党提名程序中脱颖而出的是能深刻理解成功候选人如何回答这三大问题。","targetForm":"candidates","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"This test will not select the best candidate, but it will eliminate at least some candidates with priorities that no decent political leader should have.","translation":"单靠这种方式没法选出最棒的候选人，但至少能够过滤掉部分怀着体面的政治领导人不应有的目的的竞选参与者。","targetForm":"candidate","senseId":"source-n-1","sourceSenseId":"n-1"}]},"cave":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"洞"}],"examples":[{"sentence":"A shepherd drove his snow-covered goat into an abandoned cave to take shelter from the blizzard.","translation":"一个牧羊人把他一身白雪的山羊赶进被遗弃的山洞躲避暴风雪。","targetForm":"cave","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A goatherd drove his goats, all white with snow, into a deserted cave for shelter.","translation":"一个牧羊人把他一身白雪的山羊赶进被遗弃的山洞躲避暴风雪。","targetForm":"cave","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Tom will be the first person to enter the cave.","translation":"汤姆将会是第一个进入那洞穴的人。","targetForm":"cave","senseId":"source-n-1","sourceSenseId":"n-1"}]},"care":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"照料"}],"examples":[{"sentence":"But there is one sector of our lives where adoption of information technology has lagged conspicuously: health care.","translation":"但生活中有一个方面采取信息技术的步伐大大地落后了，这就是医疗卫生。","targetForm":"care","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"But this change will raise challenging social and political questions as well, particularly concerning privacy preferences and health care – both already controversial issues.","translation":"但相关变化同样会引发社会政治难题，尤其是在已经争议颇多的隐私偏好和医疗保健领域。","targetForm":"care","senseId":"source-n-2","sourceSenseId":"n-2"}]},"carve":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"切开"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"雕刻"}],"examples":[{"sentence":"Most bans on gender-affirming care explicitly carve out exceptions for the only actual child genital mutilation going on, that against intersex babies.","translation":"大多数针对性别肯定照护的禁令都针对阴阳人婴儿明确规定了唯一豁免，允许他们接受真正的儿童生殖器切割。","targetForm":"carve","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The large siheyuans of these high-ranking officials and wealthy merchants often featured beautifully carved and painted roof beams and pillars and carefully landscaped gardens.","translation":"这些高官和富商的大四合院常常有精美雕刻并粉刷的横梁和柱子，并伴有精心修剪的花园。","targetForm":"carved","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The statue was carved from a block of cherry wood.","translation":"这座雕像是由樱木雕刻而成。","targetForm":"carved","senseId":"source-v-1","sourceSenseId":"v-1"}]},"calm":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"平稳"}],"examples":[{"sentence":"It's hard to stay objective and calm when it happens to you.","translation":"当事情发生在自己身上时，就无法客观冷静地处理。","targetForm":"calm","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"My friends always say I'm too calm, but my family always says I'm too annoying.","translation":"我的朋友们总是说我太安静了，而我的家人总是说我太让人烦了。","targetForm":"calm","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"It is presently very difficult to calm down and treat oneself with a book.","translation":"现在很难静下心来好好看一本书。","targetForm":"calm","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Though I am in the tiger's mouth, I am as calm as Mount Tai.","translation":"我虽然在虎口里，却是安如泰山。","targetForm":"calm","senseId":"source-n-1","sourceSenseId":"n-1"}]},"cart":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"二轮运货马车"}],"examples":[{"sentence":"Sometimes being overcautious in planning could upset the apple cart.","translation":"计划时如果过于谨慎的话，可能会反把计划搞乱。","targetForm":"cart","senseId":"source-n-1","sourceSenseId":"n-1"}]},"capture":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"抓取"}],"examples":[{"sentence":"In all of these areas, the TPP and TTIP seem to be about corporate capture, not liberalism.","translation":"在所有这些领域，两项协定似乎都与自由化无关，而是更与企业俘获策略有关（指大企业利用操纵公共政策获取利益 ） 。","targetForm":"capture","senseId":"source-n-1","sourceSenseId":"n-1"}]},"cashier":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"出纳员"}],"examples":[{"sentence":"Currently, my sister works as a cashier at a supermarket.","translation":"目前，我妹妹在一家超市当收银员。","targetForm":"cashier","senseId":"source-n-1","sourceSenseId":"n-1"}]},"cast":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"投掷"}],"examples":[{"sentence":"The demon grabbed my sister and, with howling laughter, cast her into a bottomless pit.","translation":"恶魔一把抓住了我的妹妹，一边狰狞地狂笑着，一边把她丢进了一个无底洞里。","targetForm":"cast","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The wicked witch cast a spell on the man and turned him into a bug.","translation":"恶毒的巫婆在男人身上施了咒语，把他变成了一只虫子。","targetForm":"cast","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"We also have to cast off the evil eye from her every so often.","translation":"我们也得时不时替她驱除邪眼。","targetForm":"cast","senseId":"source-n-2","sourceSenseId":"n-2"}]},"cafeteria":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"自助餐厅"}],"examples":[{"sentence":"The food in the cafeteria is cheap, and it's delicious.","translation":"餐厅的饭菜很便宜，而且很好吃。","targetForm":"cafeteria","senseId":"source-n-1","sourceSenseId":"n-1"}]},"catholic":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"天主教徒"}],"examples":[{"sentence":"Even people who don't believe in the Catholic church venerate the Pope as a symbolic leader.","translation":"甚至是不相信天主教的人也把教皇敬为一个象征性的领导者。","targetForm":"catholic","senseId":"source-n-1","sourceSenseId":"n-1"}]},"cash":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"现金"}],"examples":[{"sentence":"Older couples often appreciate cash more than gifts because they neither need nor have room for them.","translation":"年纪大的夫妻往往喜欢礼金胜于礼物, 因为他们既不需要礼物也没有空间放礼物。","targetForm":"cash","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"I use a credit card to pay for things more often than cash.","translation":"通常我用信用卡支付多过用现金。","targetForm":"cash","senseId":"source-n-1","sourceSenseId":"n-1"}]},"capacity":{"senseGroups":[{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"资格"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"能力"}],"examples":[{"sentence":"When he did lose, he demanded a recount, not as a candidate, but in his capacity as Commander-in-Chief.","translation":"在伊拉克问题上，唯一能够解释美国政府如此施压来支持伊朗青睐的马利基的原因，就是奥巴马在竞选总统选举时曾经许下要在第一届任期内从伊拉克撤军的诺言。","targetForm":"capacity","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"We also must expand our capacity to host refugees through resettlement and other legal pathways – such as student, work, and family reunification visas.","translation":"我们还必须扩大我们通过安置及其他合法途径接纳难民的能力 — — 包括发放留学、工作签证和家庭团聚签证。","targetForm":"capacity","senseId":"source-n-2","sourceSenseId":"n-2"}]},"candy":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"糖果"}],"examples":[{"sentence":"She ate candies one after another until she was completely full.","translation":"她一个接着一个不停地吃糖果，直到吃饱了为止。","targetForm":"candies","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"I prefer cakes or candies to alcohol, but I do drink.","translation":"比起酒来，我比较喜欢蛋糕、糖果，可是酒我也不是完全不喝的。","targetForm":"candies","senseId":"source-n-1","sourceSenseId":"n-1"}]},"case":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"情形"}],"examples":[{"sentence":"Many Indian cities have air pollution that is just as bad – and in some cases far worse.","translation":"煤炭也是气候变化最大的单一因素，到2050年，煤炭的使用可能导致 4亿最贫困国家人口面临严重的粮食和水短缺。","targetForm":"cases","senseId":"source-n-1","sourceSenseId":"n-1"}]},"cat":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"猫"}],"examples":[{"sentence":"One of the great mysteries of life is how a cat decides what to do next.","translation":"生活的伟大奥秘其中之一是猫如何决定下一步要做什么。","targetForm":"cat","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"It was proven that fleas living on dogs jump higher than fleas living on cats.","translation":"寄生在狗身上的跳蚤已被证明跳得比寄生在猫身上的高。","targetForm":"cats","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The cat glided along, very refined, but ended up falling, which was very embarrassing.","translation":"这只猫咪气场全开，走着猫步，相当优雅，然后摔倒了，真是糗大了。","targetForm":"cat","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"We know that a cat, whose eyes take in much more light than human eyes, can see clearly at night.","translation":"我们知道猫科动物的眼睛能够接受比人类的眼睛多得多的光线，所以夜里的时候能看得清楚。","targetForm":"cat","senseId":"source-n-1","sourceSenseId":"n-1"}]},"cater":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"提供饮食及服务"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"投合"}],"examples":[{"sentence":"The hotel can cater for guests who need simple meals without certain ingredients.","translation":"这家酒店可以为需要不含某些食材的简单餐食的客人提供服务。","targetForm":"cater","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The organisers catered lunch for volunteers who had travelled from several distant towns.","translation":"组织者为从几个远方城镇赶来的志愿者提供了午餐。","targetForm":"catered","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Good public libraries cater to readers of different ages and levels of experience.","translation":"好的公共图书馆服务于不同年龄和经验水平的读者。","targetForm":"cater","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The course does not cater solely to experts but explains basic ideas for new learners.","translation":"这门课程不只面向专家，也为新学习者解释基本概念。","targetForm":"cater","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The cafe caters for early commuters by opening before the first morning train arrives.","translation":"这家咖啡馆通过在早班火车到达前开门，为早起通勤者服务。","targetForm":"caters","senseId":"source-v-2","sourceSenseId":"v-2"}]},"cabin":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"小屋"}],"examples":[{"sentence":"Abraham Lincoln, the 16th president of the United States, was born in a log cabin in Kentucky.","translation":"美国的第十六任总统亚伯拉罕·林肯是在肯塔基州的一间木屋中出生的。","targetForm":"cabin","senseId":"source-n-1","sourceSenseId":"n-1"}]},"cartoon":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"卡通画"}],"examples":[{"sentence":"Some people say that cartoons on television are educational in themselves.","translation":"有人说电视上的卡通本身是有教育意义的。","targetForm":"cartoons","senseId":"source-n-1","sourceSenseId":"n-1"}]},"captain":{"senseGroups":[{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"首领"}],"examples":[{"sentence":"Between you and me, I don't like our new team captain.","translation":"我就只告诉你，我不喜欢我们的新队长。","targetForm":"captain","senseId":"source-n-4","sourceSenseId":"n-4"}]},"capable":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"有能力的"}],"examples":[{"sentence":"It seems as if I'm the only person here capable of doing it.","translation":"看来我是这里唯一有能力做这件事的人。","targetForm":"capable","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"careful":{"senseGroups":[{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"谨慎的"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"小心的"}],"examples":[{"sentence":"Careful planning helped the group finish the survey before the weather changed.","translation":"周密规划帮助小组在天气变化前完成了调查。","targetForm":"Careful","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The technician made a careful record of every measurement taken during the experiment.","translation":"技术员认真记录了实验中取得的每一项测量数据。","targetForm":"careful","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Be careful when carrying the glass samples because the labels can be easily damaged.","translation":"搬运玻璃样品时要小心，因为标签很容易受损。","targetForm":"careful","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"A careful reader notices when an author gives evidence and when an author merely claims.","translation":"细心的读者会注意到作者何时提供证据，何时只是提出主张。","targetForm":"careful","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The museum used careful lighting to protect the paintings while keeping details visible.","translation":"博物馆采用精心的照明，既保护画作又让细节清晰可见。","targetForm":"careful","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"calendar":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"日历"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"日程表"}],"examples":[{"sentence":"The red circle on the calendar marking the deadline causes me to fall into anxiety.","translation":"日历上画着红圈的截稿日期使我陷入了焦虑。","targetForm":"calendar","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"I'll keep the important dates in my calendar so I don't forget.","translation":"我会将重要日期记在行事历上，这样就不会忘。","targetForm":"calendar","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"In China, they celebrate New Year by the lunar calendar.","translation":"中国按阴历过新年。","targetForm":"calendar","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The first day of the first month in the Chinese lunar calendar is Spring Festival, the most important festival for the people of China.","translation":"中国农历年的一月一日为春节，是中国人民最隆重的传统节日。","targetForm":"calendar","senseId":"source-n-1","sourceSenseId":"n-1"}]},"carry":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"携带"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"传送"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"支持"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"运送"}],"examples":[{"sentence":"Please carry the sample boxes with both hands because the glass containers are fragile.","translation":"请用双手搬运样品箱，因为玻璃容器很易碎。","targetForm":"carry","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The wind carried the sound of the bell across the valley before sunrise.","translation":"日出前，风把钟声传过山谷。","targetForm":"carried","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"The bridge can carry heavy buses only after engineers complete the safety inspection.","translation":"只有工程师完成安全检查后，这座桥才能承载重型公交车。","targetForm":"carry","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The courier can carry fragile equipment safely because the vehicle has padded shelves.","translation":"这名快递员能安全运送易碎设备，因为车辆配有软垫搁架。","targetForm":"carry","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"A clear voice can carry across a quiet hall without the need for a microphone.","translation":"清晰的声音可以传遍安静大厅，不需要麦克风。","targetForm":"carry","senseId":"source-v-4","sourceSenseId":"v-4"}]},"caution":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"警示"}],"examples":[{"sentence":"For example, if a chain-smoking teacher cautions a pupil for smoking, that warning is self-contradictory.","translation":"举例说，如果一个老师警告学生不要吸烟，但自己却每天吸个不停，那么这个警告就是自相矛盾的了。","targetForm":"cautions","senseId":"source-n-3","sourceSenseId":"n-3"}]}}};
